CREATE TABLE `student_promotions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `student_id` bigint(20) unsigned NOT NULL,
  `from_academic_term_id` bigint(20) unsigned DEFAULT NULL,
  `to_academic_term_id` bigint(20) unsigned DEFAULT NULL,
  `from_year_block_id` bigint(20) unsigned DEFAULT NULL,
  `to_year_block_id` bigint(20) unsigned DEFAULT NULL,
  `promotion_status` varchar(60) NOT NULL DEFAULT 'Promoted',
  `remarks` text DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `sp_student_to_term_unique` (`student_id`,`to_academic_term_id`),
  KEY `sp_to_term_fk` (`to_academic_term_id`),
  KEY `sp_from_year_fk` (`from_year_block_id`),
  KEY `sp_to_year_fk` (`to_year_block_id`),
  KEY `sp_created_by_fk` (`created_by`),
  KEY `sp_from_status_idx` (`from_academic_term_id`,`promotion_status`),
  CONSTRAINT `sp_created_by_fk` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `sp_from_term_fk` FOREIGN KEY (`from_academic_term_id`) REFERENCES `academic_terms` (`id`) ON DELETE SET NULL,
  CONSTRAINT `sp_from_year_fk` FOREIGN KEY (`from_year_block_id`) REFERENCES `year_blocks` (`id`) ON DELETE SET NULL,
  CONSTRAINT `sp_student_fk` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sp_to_term_fk` FOREIGN KEY (`to_academic_term_id`) REFERENCES `academic_terms` (`id`) ON DELETE SET NULL,
  CONSTRAINT `sp_to_year_fk` FOREIGN KEY (`to_year_block_id`) REFERENCES `year_blocks` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
